package service; import java.util.*; import model.*;
public class DataStore {
 public static final ArrayList<Student> students=new ArrayList<>(); public static final ArrayList<Staff> staffMembers=new ArrayList<>(); public static final ArrayList<Admin> admins=new ArrayList<>(); public static final ArrayList<Service> services=new ArrayList<>(); public static final ArrayList<Counter> counters=new ArrayList<>(); public static final ArrayList<Token> tokenHistory=new ArrayList<>();
 public static final HashSet<String> studentIds=new HashSet<>(); public static final HashSet<Integer> tokenIds=new HashSet<>(); public static final HashMap<Integer,Token> tokenMap=new HashMap<>(); public static final HashMap<Integer,PriorityQueue<Token>> serviceQueues=new HashMap<>();
 public static final Comparator<Token> TOKEN_ORDER=Comparator.comparing(Token::isPriority).reversed().thenComparing(Token::getArrivalTime); public static int tokenCounter=1000;
 static { seed(); PersistenceService.load(); rebuild(); }
 private static void seed(){services.add(new Service(1,"Fee Related Queries",10));services.add(new Service(2,"Document Verification",15));services.add(new Service(3,"ID Card Services",8));services.add(new Service(4,"Scholarship Queries",12));services.add(new Service(5,"Bonafide Certificate",10));
 staffMembers.add(new Staff("S101","Amit Sharma","staff123",1));staffMembers.add(new Staff("S102","Priya Singh","staff123",2));staffMembers.add(new Staff("S103","Rahul Verma","staff123",3));
 counters.add(new Counter(1,"Counter 1",1,"S101"));counters.add(new Counter(2,"Counter 2",2,"S102"));counters.add(new Counter(3,"Counter 3",3,"S103"));counters.add(new Counter(4,"Counter 4",4,"S101"));counters.add(new Counter(5,"Counter 5",5,"S102"));admins.add(new Admin("admin","Administrator","admin123")); }
 public static void rebuild(){studentIds.clear();for(Student s:students)studentIds.add(s.getId().toLowerCase());tokenIds.clear();tokenMap.clear();serviceQueues.clear();for(Service s:services)serviceQueues.put(s.getServiceId(),new PriorityQueue<>(TOKEN_ORDER));for(Token t:tokenHistory){tokenIds.add(t.getTokenId());tokenMap.put(t.getTokenId(),t);if(t.getStatus().equals("Waiting"))serviceQueues.computeIfAbsent(t.getServiceId(),k->new PriorityQueue<>(TOKEN_ORDER)).offer(t);}for(Service s:services)serviceQueues.putIfAbsent(s.getServiceId(),new PriorityQueue<>(TOKEN_ORDER));}
 public static Service findService(int id){for(Service s:services)if(s.getServiceId()==id)return s;return null;} public static Counter findCounter(int id){for(Counter c:counters)if(c.getCounterId()==id)return c;return null;} public static void save(){PersistenceService.save();}
}
